// myCall polyfill: implicit binding via a temporary Symbol key
Function.prototype.myCall = function (ctx, ...args) {
  // null/undefined become globalThis, primitives are boxed
  ctx = ctx == null ? globalThis : Object(ctx);
  const key = Symbol('fn');          // unique key cannot clash with real props
  ctx[key] = this;                   // obj.method() makes this === obj
  try {
    return ctx[key](...args);
  } finally {
    delete ctx[key];                 // always clean up, even if fn throws
  }
};

