// Promise.all polyfill: results by index, counter, first rejection wins
function myAll(iterable) {
  return new Promise((resolve, reject) => {
    const items = Array.from(iterable);
    const results = new Array(items.length);
    let remaining = items.length;
    if (remaining === 0) return resolve([]);   // empty input resolves at once
    items.forEach((item, i) => {
      Promise.resolve(item).then(value => {    // wraps plain values and thenables
        results[i] = value;                    // index keeps input order
        if (--remaining === 0) resolve(results);
      }, reject);                              // outer reject: first failure wins
    });
  });
}

