// Debounce vs throttle on a fake clock (no real waiting)
let now = 0;
const timers = [];
const fakeSetTimeout = (fn, ms) => { const t = { at: now + ms, fn, on: true }; timers.push(t); return t; };
const fakeClear = t => { if (t) t.on = false; };
function advance(to) {                       // run due timers in order
  for (;;) {
    const due = timers.filter(t => t.on && t.at <= to).sort((a, b) => a.at - b.at)[0];
    if (!due) break;
    due.on = false; now = due.at; due.fn();
  }
  now = to;
}

function debounce(fn, wait) {
  let t;
  return (...a) => { fakeClear(t); t = fakeSetTimeout(() => fn(...a), wait); }; // each event resets
}
function throttle(fn, wait) {
  let last = -Infinity, t, pending;
  return (...a) => {
    pending = a;
    if (now - last >= wait) { last = now; fn(...a); pending = null; }     // leading call
    else if (!t || !t.on) t = fakeSetTimeout(() => {                      // trailing call
      last = now; fn(...pending); pending = null;
    }, wait - (now - last));
  };
}

