// deepEqual with cycle memo, Dates, Sets, NaN and key-order independence
function deepEqual(a, b, memo = new WeakMap()) {
  if (Object.is(a, b)) return true;              // same ref, and NaN equals NaN
  if (typeof a !== 'object' || typeof b !== 'object' || !a || !b) return false;
  if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false;
  if (a instanceof Date) return a.getTime() === b.getTime();
  if (a instanceof RegExp) return a.source === b.source && a.flags === b.flags;
  if (!memo.has(a)) memo.set(a, new WeakSet());
  if (memo.get(a).has(b)) return true;           // pair in progress: assume equal
  memo.get(a).add(b);
  if (a instanceof Set) {                        // O(n^2) for object members
    if (a.size !== b.size) return false;
    return [...a].every(x => [...b].some(y => deepEqual(x, y, memo)));
  }
  const ka = Reflect.ownKeys(a), kb = Reflect.ownKeys(b);
  if (ka.length !== kb.length) return false;
  return ka.every(k => Object.prototype.hasOwnProperty.call(b, k) && deepEqual(a[k], b[k], memo));
}

