// curry: collect args across calls until fn.length are available
function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) return fn(...args);
    // return a new function; concat (not push) keeps partials reusable
    return (...more) => curried(...args, ...more);
  };
}
