// EventEmitter with snapshot emit, once wrapper, and guarded off
class Emitter {
  constructor() { this.map = new Map(); }
  on(name, fn) {
    if (!this.map.has(name)) this.map.set(name, []);
    this.map.get(name).push(fn);
    return () => this.off(name, fn);             // unsubscribe closure
  }
  off(name, fn) {
    const list = this.map.get(name);
    if (!list) return;
    const i = list.findIndex(l => l === fn || l.original === fn);
    if (i !== -1) list.splice(i, 1);             // guard: splice(-1,1) removes the last item
    if (list.length === 0) this.map.delete(name);// no leaked empty lists
  }
  once(name, fn) {
    const wrapper = (...a) => { this.off(name, wrapper); fn(...a); };
    wrapper.original = fn;                       // lets off(name, fn) find it
    return this.on(name, wrapper);
  }
  emit(name, ...args) {
    const list = this.map.get(name);
    if (!list) return false;
    [...list].forEach(l => l(...args));          // snapshot: edits during emit are safe
    return true;
  }
}

