// retry with exponential backoff + full jitter; sleep and random are injectable
async function retry(fn, { retries = 4, base = 100, max = 1000,
                           sleep, random = Math.random, retryable = () => true } = {}) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      if (attempt >= retries || !retryable(err)) throw err; // give up: rethrow last error
      const cap = Math.min(max, base * 2 ** attempt);       // exponential cap
      const wait = Math.floor(random() * cap);              // full jitter: 0..cap
      console.log(`attempt ${attempt} failed (${err.message}); wait ${wait}ms (cap ${cap})`);
      await sleep(wait);
    }
  }
}

