// LRU cache using Map insertion order (oldest key is first)
class LRU {
  constructor(cap) { this.cap = cap; this.m = new Map(); }
  get(k) {
    if (!this.m.has(k)) return undefined;
    const v = this.m.get(k);
    this.m.delete(k); this.m.set(k, v);          // re-insert: now the newest
    return v;
  }
  put(k, v) {
    this.m.delete(k);                            // updating also refreshes recency
    this.m.set(k, v);
    if (this.m.size > this.cap) {
      const oldest = this.m.keys().next().value; // first key = least recently used
      this.m.delete(oldest);
      console.log('evicted', oldest);
    }
  }
  keys() { return [...this.m.keys()].join(','); }
}

