// Promise pool: N workers share a cursor and pull the next task when free
async function pool(tasks, limit) {
  const results = new Array(tasks.length);
  let next = 0, running = 0, peak = 0;
  async function worker() {
    while (next < tasks.length) {
      const i = next++;                          // claim an index synchronously
      running++; peak = Math.max(peak, running);
      try { results[i] = { ok: true, value: await tasks[i]() }; }
      catch (e) { results[i] = { ok: false, error: e.message }; } // allSettled-style
      running--;
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, tasks.length) }, worker));
  return { results, peak };
}

